#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ipos = 0, ilen = 0;
static inline int gc() {
    if (ipos == ilen) { ilen = fread(ibuf, 1, sizeof ibuf, stdin); ipos = 0; if (!ilen) return -1; }
    return ibuf[ipos++];
}
static inline long long readInt() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

int main() {
    int n = readInt(), m = readInt();
    vector<long long> a(n);
    for (auto& x : a) x = readInt();
    sort(a.begin(), a.end());
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    string out;
    out.reserve((size_t)m * 24);
    for (int k = 0; k < m; k++) {
        long long low = readInt(), high = readInt();
        // Closed range [low, high] is the sorted block [l, r).
        size_t l = lower_bound(a.begin(), a.end(), low) - a.begin();
        size_t r = upper_bound(a.begin(), a.end(), high) - a.begin();
        if (r < l) r = l;
        out += to_string(r - l);
        out += ' ';
        out += to_string(prefix[r] - prefix[l]);
        out += '\n';
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));

    static long readLong() throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long x = 0;
        while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = in.read(); }
        return neg ? -x : x;
    }

    // First index with a[i] >= key (or > key when strict).
    static int bound(long[] a, long key, boolean strict) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < key || (strict && a[mid] == key)) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) readLong(), m = (int) readLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = readLong();
        Arrays.sort(a);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
        StringBuilder out = new StringBuilder(m * 24);
        for (int k = 0; k < m; k++) {
            long low = readLong(), high = readLong();
            // Closed range [low, high] is the sorted block [l, r).
            int l = bound(a, low, false), r = Math.max(l, bound(a, high, true));
            out.append(r - l).append(' ').append(prefix[r] - prefix[l]).append('\n');
        }
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"slices"
	"sort"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, _ := reader.ReadByte()
	for c != '-' && (c < '0' || c > '9') {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	var x int64
	for c >= '0' && c <= '9' {
		x = x*10 + int64(c-'0')
		var err error
		c, err = reader.ReadByte()
		if err != nil {
			break
		}
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	n, m := int(readInt()), int(readInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = readInt()
	}
	slices.Sort(a)
	prefix := make([]int64, n+1)
	for i, v := range a {
		prefix[i+1] = prefix[i] + v
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	buf := []byte{}
	for k := 0; k < m; k++ {
		low, high := readInt(), readInt()
		// Closed range [low, high] is the sorted block [l, r).
		l := sort.Search(n, func(i int) bool { return a[i] >= low })
		r := max(l, sort.Search(n, func(i int) bool { return a[i] > high }))
		buf = strconv.AppendInt(buf[:0], int64(r-l), 10)
		buf = append(buf, ' ')
		buf = strconv.AppendInt(buf, prefix[r]-prefix[l], 10)
		buf = append(buf, '\n')
		w.Write(buf)
	}
}
